import { useState } from 'react';
import { useStore } from '../lib/store';
import { FileText, Plus, Trash2, Clock, Search, Edit2, Check, X, LayoutGrid, List } from 'lucide-react';
import './styles/TextEntriesManager.css';

function TextEntriesManager({ resources }) {
    const { addResource, deleteResource, updateResource, currentVersion } = useStore();
    const [newEntry, setNewEntry] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [editingId, setEditingId] = useState(null);
    const [editText, setEditText] = useState('');
    const [viewMode, setViewMode] = useState('list'); // 'list' | 'cards'

    const handleAddEntry = async () => {
        if (!newEntry.trim() || !currentVersion) return;

        setIsSubmitting(true);
        try {
            await addResource(currentVersion.id, {
                type: 'note',
                name: 'Note',
                metadata: {
                    content: newEntry.trim()
                }
            });
            setNewEntry('');
        } catch (error) {
            console.error('Failed to add note:', error);
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleKeyDown = (e) => {
        if (e.key === 'Enter' && e.ctrlKey) {
            handleAddEntry();
        }
    };

    const startEditing = (entry) => {
        setEditingId(entry.id);
        setEditText(entry.metadata?.content || '');
    };

    const cancelEditing = () => {
        setEditingId(null);
        setEditText('');
    };

    const saveEdit = async (id) => {
        if (!editText.trim()) return;
        try {
            await updateResource(id, {
                metadata: { content: editText.trim() }
            });
            setEditingId(null);
            setEditText('');
        } catch (error) {
            console.error('Failed to update note:', error);
        }
    };

    const handleEditKeyDown = (e, id) => {
        if (e.key === 'Enter' && e.ctrlKey) {
            saveEdit(id);
        } else if (e.key === 'Escape') {
            cancelEditing();
        }
    };

    const formatDate = (date) => {
        if (!date) return '';
        return new Intl.DateTimeFormat('en-US', {
            month: 'short',
            day: 'numeric',
            year: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        }).format(date);
    };

    // Filter notes by search query
    const filteredResources = resources.filter(entry => {
        const content = entry.metadata?.content || entry.metadata?.text || '';
        return content.toLowerCase().includes(searchQuery.toLowerCase());
    });

    // Helper to render text with clickable links
    const renderContentWithLinks = (text) => {
        if (!text) return '';
        
        // Regex to match URLs (http, https)
        const urlRegex = /(https?:\/\/[^\s]+)/g;
        const parts = text.split(urlRegex);
        
        return parts.map((part, i) => {
            if (part.match(urlRegex)) {
                return (
                    <a 
                        key={i} 
                        href={part} 
                        target="_blank" 
                        rel="noopener noreferrer"
                        className="note-link"
                        onClick={(e) => e.stopPropagation()}
                    >
                        {part}
                    </a>
                );
            }
            return part;
        });
    };

    // Subtle background tint per card index
    const getCardTint = (index) => {
        const tints = [
            'var(--note-tint-1, rgba(255,255,255,0.02))',
            'var(--note-tint-2, rgba(100,180,255,0.04))',
            'var(--note-tint-3, rgba(180,100,255,0.03))',
            'var(--note-tint-4, rgba(100,255,180,0.03))',
            'var(--note-tint-5, rgba(255,200,100,0.03))',
        ];
        return tints[index % tints.length];
    };

    return (
        <div className="text-entries">
            <div className="entries-header">
                <h3>
                    <FileText size={18} />
                    Project Notes
                </h3>
                <div className="entries-header-right">
                    <div className="entries-search">
                        <Search size={14} />
                        <input
                            type="text"
                            placeholder="Search notes..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="search-input"
                        />
                    </div>
                    <div className="entries-view-toggle">
                        <button
                            className={`btn btn-icon btn-ghost btn-sm ${viewMode === 'list' ? 'active' : ''}`}
                            onClick={() => setViewMode('list')}
                            title="List view"
                        >
                            <List size={16} />
                        </button>
                        <button
                            className={`btn btn-icon btn-ghost btn-sm ${viewMode === 'cards' ? 'active' : ''}`}
                            onClick={() => setViewMode('cards')}
                            title="Card view"
                        >
                            <LayoutGrid size={16} />
                        </button>
                    </div>
                </div>
            </div>

            <div className="entries-input-wrapper">
                <textarea
                    className="input entry-textarea"
                    placeholder="Type a note... (Ctrl+Enter to add)"
                    value={newEntry}
                    onChange={(e) => setNewEntry(e.target.value)}
                    onKeyDown={handleKeyDown}
                />
                <div className="entries-input-actions">
                    <button
                        className="btn btn-primary btn-sm"
                        onClick={handleAddEntry}
                        disabled={!newEntry.trim() || isSubmitting}
                    >
                        <Plus size={16} />
                        Add Note
                    </button>
                </div>
            </div>

            <div className="entries-content">
                {filteredResources.length === 0 ? (
                    <div className="entries-empty">
                        <FileText size={48} />
                        <h3>{searchQuery ? 'No matching notes' : 'No notes yet'}</h3>
                        <p>{searchQuery ? 'Try a different search term.' : 'Add notes, ideas, or logs for this version.'}</p>
                    </div>
                ) : (
                    <div className={`entries-list ${viewMode === 'cards' ? 'entries-grid' : ''}`}>
                        {filteredResources.map((entry, index) => (
                            <div
                                key={entry.id}
                                className={`entry-card ${editingId === entry.id ? 'editing' : ''}`}
                                style={{ background: getCardTint(index) }}
                            >
                                <div className="entry-header">
                                    <span className="entry-timestamp">
                                        <Clock size={12} />
                                        {formatDate(entry.createdAt)}
                                    </span>
                                    <div className="entry-actions">
                                        {editingId === entry.id ? (
                                            <>
                                                <button
                                                    className="btn btn-icon btn-ghost btn-sm text-success"
                                                    onClick={() => saveEdit(entry.id)}
                                                    title="Save (Ctrl+Enter)"
                                                >
                                                    <Check size={14} />
                                                </button>
                                                <button
                                                    className="btn btn-icon btn-ghost btn-sm"
                                                    onClick={cancelEditing}
                                                    title="Cancel (Esc)"
                                                >
                                                    <X size={14} />
                                                </button>
                                            </>
                                        ) : (
                                            <>
                                                <button
                                                    className="btn btn-icon btn-ghost btn-sm"
                                                    onClick={() => startEditing(entry)}
                                                    title="Edit note"
                                                >
                                                    <Edit2 size={14} />
                                                </button>
                                                <button
                                                    className="btn btn-icon btn-ghost btn-sm text-error"
                                                    onClick={() => deleteResource(entry.id)}
                                                    title="Delete note"
                                                >
                                                    <Trash2 size={14} />
                                                </button>
                                            </>
                                        )}
                                    </div>
                                </div>
                                {editingId === entry.id ? (
                                    <textarea
                                        className="input entry-edit-textarea"
                                        value={editText}
                                        onChange={(e) => setEditText(e.target.value)}
                                        onKeyDown={(e) => handleEditKeyDown(e, entry.id)}
                                        autoFocus
                                    />
                                ) : (
                                    <div
                                        className="entry-content"
                                        onClick={() => startEditing(entry)}
                                    >
                                        {renderContentWithLinks(entry.metadata?.content || entry.metadata?.text || '')}
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}

export default TextEntriesManager;
